<script setup>
    import { onMounted, ref,inject,watch,nextTick } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    import '@/assets/sass/scrollspyNav.scss';
    const selected_machine = ref(null);
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const selected_service = ref('');
    const machine_filter = ref(null);
    const current_km_of_service = ref('');
    const next_km_of_service = ref('');
    const loading_spinner = ref(true);
    const jobcard_registration = ref(false);
    const loader = ref(false);
    const Machines = ref([]);
    const services = ref([]);
    const showMessage = inject('showMessage');
    const showError = inject('showError');
    const tableShimmer = inject('tableShimmer');
    const refreshButton = inject('refreshButton')
    useMeta({ title: 'Jobcard Lists' });
    const source = ref(localStorage.getItem('source'))
   const filter_jobcard = ref(false)


import { useRouter } from 'vue-router';

const router = useRouter();

const handleJobcardOpen = (jobcard) => {
    if (jobcard.status_id === 1 && !user_permissions.includes('can_open_jobcard')) {
        showError('jobcard needs approval from workshop officer');
        return;
    }
    router.push(`/jobcard/${jobcard.id}/${jobcard.machine_id}`);
};

    const jobcardData = ref ([])
const jobcardSummary = async (id) => {
  loader.value = true;
    try {
        const response = await axiosInstance.get(`/jobcard-summary?asset_id=${id}`);
        jobcardData.value = response.data;

        await nextTick(); // ensures reactivity is done updating
        printJobcardSummary();
        
    } catch (error) {
        showError(error.message);
        console.error("Error fetching jobcard summary:", error);
    }
};

const printJobcardSummary = () => {
  const jobcards = jobcardData.value || [];

  loader.value = false;
  const iframe = document.createElement("iframe");
  iframe.style.display = "none";
  document.body.appendChild(iframe);

  const printContent = `
<!DOCTYPE html>
<html>
<head>
<title>Jobcard Summary</title>
<style>
  body { font-family: Arial, sans-serif; margin: 40px; font-size: 13px; }
  .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10px; }
  .logo { width: 150px; height: auto; }
  .company-title { text-align: center; margin-top: 5px; }
  .company-title h2 { margin: 5px 0; }
  .reg-info { position: absolute; top: 40px; right: 40px; text-align: right; font-size: 10px; line-height: 1.4; font-weight: normal; }
  table { width: 100%; border-collapse: collapse; margin-top: 20px; }
  th, td { border: 1px solid #000; padding: 6px; text-align: center; }
  th { background-color: #f8f8f8; }
</style>
</head>
<body>

<div class="header">
  <img src="https://bushman.ink/copex.jpg" class="logo" />
  <div class="reg-info">
    TIN: 135-489-247<br>
    VRN: 40-032826C
  </div>
</div>

<div class="company-title">
  <h2>COPEX CONTRACTORS CO.LTD</h2>
  <div>Msamvu, P.O.BOX 678, Morogoro</div>
  <div>Mobile: 0713 000 777, 0657 111 555</div>
</div>


<table>
  <thead>
    <tr>
      <th>${machine_filter.value.category.name}</th>
      <th>TYPE</th>
    </tr>
  </thead>
  <tbody>
      <tr>
        <td>${machine_filter.value.name}</td>
        <td>${machine_filter.value.type_name}</td>
      </tr>
  </tbody>
</table>

<h2 style="text-align:center; margin-top: 20px;">Jobcard Summary</h2>

<table>
  <thead>
    <tr>
      <th>SN</th>
      <th>Jobcard NO</th>
      <th>Date Created</th>
      <th>Service Type</th>
      <th>Current Km Service</th>
      <th>Next Km Service</th>
      <th>Status</th>
      <th>Total Sum</th>
    </tr>
  </thead>
  <tbody>
    ${jobcards.map((jc, index) => `
      <tr>
        <td>${index + 1}</td>
        <td>${jc.id}</td>
        <td>${jc.date_created}</td>
        <td>${jc.service_type}</td>
        <td>${jc.current_km_service}</td>
        <td>${jc.next_km_service}</td>
        <td>${jc.status_name}</td>
        <td style="text-align:right">${parseFloat(jc.total_sum).toLocaleString()}/=</td>
      </tr>
    `).join("")}
    <tr>
      <td colspan="7" style="text-align:right"><strong>Grand Total</strong></td>
      <td style="text-align:right"><strong>${
        jobcards.reduce((sum, jc) => sum + parseFloat(jc.total_sum || 0), 0).toLocaleString()
      }/=</strong></td>
    </tr>
  </tbody>
</table>




</body>
</html>
`;

  const iframeDoc = iframe.contentWindow.document;
  iframeDoc.open();
  iframeDoc.write(printContent);
  iframeDoc.close();

  iframe.onload = () => {
    iframe.contentWindow.focus();
    iframe.contentWindow.print();
    setTimeout(() => {
      document.body.removeChild(iframe);
    }, 1000);
  };
};


    const columns = ref(['Sno','date_created','jobcard_id', 'name','location','issuer','days_open','service_type','current_svc','next_svc','status','actions']);
    const items = ref([]);
    const table_option = ref({
        perPage: 50,
        perPageValues: [ 50,100,200,500,1000],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['id', 'vehicle_no','date','service_type','current_service_kms','next_service_kms','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const machine_id = ref(null);

   const filter_machine = ref(null);
   const header = ref('JOBCARD LIST')
  const date = ref(new Date().toISOString().split('T')[0]);
const fetchJobCards = async() => {
    loading_spinner.value = true
   try{
     let url = `job-card?date_created=${filter_machine.value ? 'all' : date.value}`;
     
     if (filter_machine.value) {
         url += `&asset_id=${filter_machine.value.id}`;
     }
     
     const response = await axiosInstance.get(url)
     items.value = response.data.map((item,index)=>({
      ...item,
      Sno : index + 1,
      jobcard_id : item.id,
      name : item.machine.name + ' - ' + item.machine.type_name,
      location : item.location?.name,
      issuer : item.issuer?.name,
      current_svc : item.current_km_of_service,
      next_svc : item.next_km_of_service,
      // days_open : item.days_open.toLocaleString() ?? '---',
      status : {
        key : item.status.name,
        class : item.status.color
      }
     }))
     filteredJobcards.value = items.value
   }catch(error){
    console.log(error)
    showError(error.message)
   }finally{
    loading_spinner.value = false
   }
};

watch(date, () => {
    filter_machine.value = null;
    fetchJobCards();
});

watch(filter_machine, () => {
    // date.value = 'null';
    fetchJobCards();
});

     const location = ref('');
    const date_created = ref('')
    const alert = ref('')
  const registerJobcard = () => {
    jobcard_registration.value = false;
    const jobcardData = {
        machine_id: selected_machine.value.id,
        machine_name: selected_machine.value.name,
        status_name: location.value.id === 2 ? 'Inactive' : 'Active',
        status_color: location.value.id === 2 ? 'dark' : 'primary',
        status_id: location.value.id === 2 ? 1 : 6,
        service_type: services.value.find(service => service.id === selected_service.value).name,
        current_km_of_service: current_km_of_service.value,
        next_km_of_service: next_km_of_service.value,
        date_created: date_created.value,
        company_id: company.value.id,
        issuer_id: JSON.parse(localStorage.getItem("user")).id,
        location_id: location.value.id,
        service_type_id : selected_service.value
    };

    axiosInstance
        .post('/job-card', jobcardData)
        .then((response) => {
            fetchJobCards();
            showMessage('Jobcard registered successfully!');
        })
        .catch((error) => {
            showError(error.message);
            console.log(error);
            if(error.status == 422){
              alert.value = error.response.data.message
            }
        });
};

const fetchServices = () =>{
      axiosInstance
        .get(`/service-type`)
        .then((response) => {
          if (Array.isArray(response.data)) {
            services.value = response.data;
          } else {
            console.error("Invalid response format");
          }
        })
        .catch((error) => {
          console.error("Error fetching user data:", error.message);
        })
        .finally(() => {
        });
    }

    const fetchMachines = async () => {
      try {
        const response = await axiosInstance.get(`/machines`);
        if (Array.isArray(response.data)) {
          Machines.value = response.data.map(machine => ({
            id: machine.id,
            name: machine.name + ' - ' + machine.type_name,
            type: machine.type_name,  
            asset: machine.name + ' - ' + machine.type_name        
          }));
        } else {
          console.error("Invalid response format");
        }
      } catch (error) {
        console.error("Error fetching machine data:", error.message);
      } finally {
      }
    }

const deleteJobcard = (jobcardId) => {
    if (confirm('Are you sure you want to delete this jobcard?')) {
        axiosInstance
            .delete(`/job-card/${jobcardId}`)
            .then((response) => {
                fetchJobCards();
                alert('Jobcard deleted successfully!');
                if (response.data.status === 200) {
                    fetchJobCards();
                } else {
                    console.error("Error deleting jobcard:", response.data.message);
                }
            })
            .catch((error) => {
                console.error("Error deleting jobcard:", error.message);
            });
    }
};

const companies= ref([])
const company = ref('')
const getCompanies = async()=>{
  const response = await axiosInstance.get('companies')
  companies.value = response.data
}

const filteredJobcards = ref([])
        watch(company, (newVal) => {
    if (newVal) {
         filteredJobcards.value = items.value.filter(card => card.company_id === newVal.id)
    }else{
      filteredJobcards.value = items.value
    }
});

const openEditModal = async (jobcard) => {
  await getLocations()
    selected_machine.value = Machines.value.find(machine => machine.id === jobcard.machine_id);
    current_km_of_service.value = jobcard.current_km_of_service;
    next_km_of_service.value = jobcard.next_km_of_service;
    jobcard_id.value = jobcard.id;
    editModal.value = true;
    location.value = locations.value.find(location => location.id === jobcard.location_id);
    selected_service.value = services.value.find(service => service.name === jobcard.service_type).id
    console.log(locations.value)
}

const jobcard_id = ref(null);
const editModal = ref(false);
const loading = ref(false)
const updateJobcard = async () => {
    loading.value = true;
    try {
        const payload = {
            current_km_of_service: current_km_of_service.value,
            next_km_of_service: next_km_of_service.value,
            location_id: location.value.id,
            service_type: services.value.find(service => service.id === selected_service.value).name,
            service_type_id : selected_service.value
        };
        await axiosInstance.put(`/job-card/${jobcard_id.value}`, payload);
        showMessage('Jobcard updated successfully!');
        document.getElementById('close_editing').click();
        closeEditModal();
        fetchJobCards();
    } catch (error) {
        showError(error.message);
        console.log(error);
    } finally {
        loading.value = false;
    }
};
const waitIndicator = inject('waitIndicator')
const closeEditModal = () => {
    selected_machine.value = null;
    current_km_of_service.value = '';
    next_km_of_service.value = '';
    jobcard_id.value = null;
    editModal.value = false;
    location.value = '',
    selected_service.value = ''
};


const locations = ref([]);
const getLocations = async()=>{
    loading.value = true
  try{
  const response = await axiosInstance.get('locations')
  locations.value = response.data
  }catch(error){
    showError(error.message)
    console.log(error)
  }finally{
    loading.value = false
  }

}

    onMounted(() => {
        getCompanies();
        fetchJobCards();
        fetchServices();
        fetchMachines();
    });
</script>

